import copy


class TaskBatch:
    def __init__(self):
        self._items = []
        self._closed = False

    @property
    def closed(self):
        return self._closed

    def add(self, payload):
        if self._closed:
            raise RuntimeError("batch is closed")
        self._items.append(copy.deepcopy(payload))

    def close(self):
        self._closed = True
        self._items.clear()

    def drain(self):
        items = self._items
        self._items = []
        return items

    def __len__(self):
        return len(self._items)
